import { test, expect } from '@playwright/test';
import { resetAndSeed } from '../support/seed';

test.describe('grade tally merged', () => {
  test('MID folded into HIGH', { tag: '@functionality' }, async ({ page }) => {
    await resetAndSeed({
      people: [
        { id: 1, name: 'Ada', alpha: 10, beta: 50, gamma: 10, grade: 'HIGH', state: 'FINAL', active: true },
        { id: 2, name: 'Ben', alpha: 10, beta: 30, gamma: 10, grade: 'MID', state: 'FINAL', active: true },
        { id: 3, name: 'Cam', alpha: 10, beta: 20, gamma: 10, grade: 'LOW', state: 'REVIEW', active: true },
        { id: 4, name: 'Dot', alpha: 4, beta: 30, gamma: 4, grade: 'HIGH', state: 'DRAFT', active: true },
        { id: 5, name: 'Eli', alpha: 8, beta: 10, gamma: 8, grade: 'MID', state: 'DRAFT', active: true },
        { id: 6, name: 'Fin', alpha: 2, beta: 30, gamma: 2, grade: 'LOW', state: 'REVIEW', active: true },
        { id: 7, name: 'Gwe', alpha: 5, beta: 1, gamma: 0, grade: 'HIGH', state: 'DRAFT', active: true },
      ],
    });
    await page.goto('/');
    await expect(page.getByTestId('grade-tally-HIGH')).toHaveText('5');
    await expect(page.getByTestId('grade-tally-LOW')).toHaveText('2');
    await expect(page.getByTestId('grade-tally-MID')).toHaveText('0');
  });
});
# OfficeHQ

A full-stack office-management web application.

- **Front end:** Angular single-page app (standalone components, lazy routes), built into
  `src/main/resources/static`.
- **Back end:** Spring Boot with Spring MVC `@RestController` endpoints, on an in-memory H2 database
  with Flyway migrations run on boot.

## Build and run

```
bin/build              # build the SPA and package one runnable jar
PORT=3000 bin/start    # start the app (serves the SPA + REST on $PORT)
bin/stop               # stop it
```

Readiness: `GET /actuator/health`.

## Tests

End-to-end tests use Playwright (in `e2e/`) and bind to `data-testid`:

```
bin/e2e                # build, start, run the specs in e2e/specs, then stop
```

